import type Phaser from 'phaser';
import { CASES } from '../game/cases';
import { DAILY_QUEST, ITEMS, STORY_CHAPTERS, RECIPES, SIDE_QUESTS, SKILLS, ZONES, type ItemInfo } from '../game/content';
import { addItem, dayKey, grantXp, levelForXp, migrateProfile, rankForScore, removeItem, DEFAULT_PROFILE } from '../game/progression';
import { makeSyntheticXray, scoreExposure, type Score } from '../game/simulation';
import type { CaseInfo, GameView, Profile, Technique } from '../game/types';

const SAVE_KEY='radtech-pixel-profile';
function readProfile():Profile { try { return migrateProfile(JSON.parse(localStorage.getItem(SAVE_KEY)||'null')); } catch { return migrateProfile(null); } }
const profile=readProfile();
let view:GameView=profile.currentZone==='noise-lab'?'dungeon':'hub', activeCase:CaseInfo=CASES[0], step=0, verified=false, positioned=false, collimated=false, breath=false, patientReady=false, score:Score|null=null, xray='';
let technique:Technique={kvp:110,ma:31.25,mas:2.5,sid:180,oid:8,time:.08,grid:false,aec:false};
let gameRef:Phaser.Game|null=null;
let sceneView='hospital',dialogueKind='welcome',dialogueText='ยินดีต้อนรับสู่แผนกรังสี! ไปพบพี่มายาเพื่อรับภารกิจแรกนะ',dialogueName='MAYA · SENIOR TECHNOLOGIST',touchDirection:string|null=null;
let overlayPanel:GameView|null=null;
let miniGame:'positioning'|'collimation'|'timing'|null=null,positionChoice='PA',patientOffset=2,poseChoice='rest',collimationChoice='optimal',timingStarted=0,timingMessage='';
let inventoryTab:'bag'|'equipment'|'collection'='bag',encounter:{enemy:{id:string;name:string;hp:number;maxHp:number;boss:boolean};question:{question:string;choices:string[];answer:number;feedback:string;topic?:string}}|null=null,combatFeedback='',combatCorrect=false,combatSkillActive:''|'noise-detection'|'anatomy-scan'='',scanActive:'anatomy'|'noise'|''='';
const root=document.querySelector<HTMLDivElement>('#app')!;
const base=import.meta.env.BASE_URL;
const save=()=>localStorage.setItem(SAVE_KEY,JSON.stringify(profile));
const item=(id:string)=>ITEMS.find(entry=>entry.id===id);
function grant(id:string,quantity=1){if(item(id))addItem(profile,id,quantity);}
function owns(id:string){return (profile.inventory[id]||0)>0;}
function awardQuest(id:string,xp:number,coins:number,itemId?:string){if(profile.completedQuests.includes(id))return false;profile.completedQuests.push(id);grantXp(profile,xp);profile.coins+=coins;if(itemId)grant(itemId);save();return true;}
function unlocked(c:CaseInfo){return profile.unlockedSkills.includes('projection-mastery')||profile.completed.length>=c.unlockedAt;}
function nav(active:string){return `<nav class="top-nav"><div class="brand"><span class="brand-mark">✦</span><span>RADTECH <b>PIXEL</b><small>THE X-RAY CHRONICLES</small></span></div><div class="nav-links"><button data-view="hub" class="${active==='hub'?'selected':''}">⌂ <span>Lobby</span></button><button data-view="library" class="${active==='library'?'selected':''}">▦ <span>Case files</span></button><button data-view="learn" class="${active==='learn'?'selected':''}">✦ <span>Learning</span></button></div><div class="profile-pill"><div class="avatar">✿</div><span><b>Radiography Student</b><small>LEVEL 1 · INTERN</small></span><div class="xp-mini"><i style="width:${profile.xp%100}%"></i></div></div><div class="currency">♥ <b>3</b><span>🪙 ${profile.coins}</span><button class="icon-btn" data-view="results" title="Training log">⚙</button></div></nav>`;}
function footer(){return `<footer><span>RADTECH PIXEL <i>·</i> TRAINING SIMULATION</span><span>✦ ${profile.xp} XP &nbsp; · &nbsp; ${profile.completed.length}/${CASES.length} CASES</span></footer>`;}
function appShell(active:string,body:string){root.innerHTML=`<div class="app-shell">${nav(active)}<main>${body}</main>${footer()}<div class="safety-ribbon">SIMULATION ONLY · NOT FOR DIAGNOSIS OR CLINICAL USE</div></div>`; bind();}
function worldShell(body:string){root.innerHTML=`<div class="world-shell">${body}</div>`;bindRpg();}
function questObjective(){return ['พบพี่มายาเพื่อรับภารกิจแรก','ไปรับใบส่งตรวจที่เคาน์เตอร์','เดินไปยังประตูแผนกรังสีแล้วกด E','ทำภารกิจ Chest PA ให้เสร็จ','นำผลการฝึกไปคุยกับคุณหมอ','เควสต์แรกสำเร็จ!'][Math.min(profile.questStep,5)];}
function windowPanel(kicker:string,title:string,body:string){return `<section class="rpg-window modal-window"><button class="window-close" data-view="hub" aria-label="ปิด">×</button><span class="pixel-kicker">${kicker}</span><h2>${title}</h2>${body}<button class="pixel-button" data-view="hub">กลับล็อบบี้</button></section>`;}
function itemCard(id:string,count:number){const entry=item(id);if(!entry)return '';return `<article class="inventory-card rarity-${entry.rarity}"><span class="inventory-icon">${entry.icon}</span><div><b>${entry.name}</b><small>${entry.description}</small><em>ที่มา: ${entry.source}</em></div><strong>×${count}</strong>${entry.slot&&count?`<button data-action="equip" data-item="${id}">${profile.equipped.includes(id)?'ถอด':'สวมใส่'}</button>`:''}${id==='medical-supply'&&count?'<button data-action="use-item" data-item="medical-supply">ใช้</button>':''}</article>`;}
function questPanel(){
  const side=SIDE_QUESTS.map(q=>{const active=profile.activeQuests.includes(q.id),done=profile.completedQuests.includes(q.id);const ready=q.id==='library-notes'?profile.completed.length>0:q.id==='equipment-check'?owns('basic-scanner'):profile.hiddenFinds.includes('garden-cache');return `<article class="quest-card"><div><b>${q.name}</b><small>${q.giver} · ${q.description}</small><span>${q.objective} · ${q.rewardXp} EXP · ${q.rewardCoins} เหรียญ</span></div>${done?'<strong>✓ เสร็จแล้ว</strong>':active?(ready?`<button data-action="claim-side" data-quest="${q.id}">รับรางวัล</button>`:'<strong>กำลังทำ</strong>'):`<button data-action="accept-side" data-quest="${q.id}">รับภารกิจ</button>`}</article>`;}).join('');
  const dailyReady=profile.activeQuests.includes(DAILY_QUEST.id)&&profile.missions>profile.dailyStartMissions;
  const dailyDone=profile.dailyClaimDate===dayKey();
  const story=STORY_CHAPTERS.map(chapter=>`<article class="quest-card chapter ${chapter.id===profile.chapter?'current':chapter.id<profile.chapter?'complete':'locked'}"><div><b>${chapter.id<profile.chapter?'✓':`CH.${chapter.id}`} · ${chapter.title}</b><small>${chapter.summary}</small><span>ตัวละคร: ${chapter.mentor} · ${chapter.playable?'เล่นได้ใน build นี้':chapter.gate}</span></div><strong>${chapter.id<profile.chapter?'จบแล้ว':chapter.id===profile.chapter?'ปัจจุบัน':chapter.playable?'ปลดล็อกแล้ว':'วางแผน'}</strong></article>`).join('');
  return windowPanel('MISSION BOARD','กระดานภารกิจ',`<article class="quest-card main"><div><b>บทที่ ${profile.chapter} · ${STORY_CHAPTERS[Math.min(profile.chapter-1,STORY_CHAPTERS.length-1)].title}</b><small>${questObjective()}</small><span>เควสต์หลัก · ทำต่อได้จาก NPC และประตูห้อง</span></div><strong>${profile.questStep>=5?'✓':'กำลังทำ'}</strong></article><h3 class="panel-subtitle">เส้นเรื่อง 5 บท</h3><div class="chapter-list">${story}</div><article class="quest-card"><div><b>${DAILY_QUEST.name}</b><small>${DAILY_QUEST.description}</small><span>รีเซ็ตตามวันที่ประเทศไทย · รางวัล ${DAILY_QUEST.rewardXp} EXP + ชุดอุปกรณ์ฝึก</span></div>${dailyDone?'<strong>✓ วันนี้รับแล้ว</strong>':dailyReady?'<button data-action="claim-daily">รับรางวัล</button>':profile.activeQuests.includes(DAILY_QUEST.id)?'<strong>ทำเคส 1 ครั้ง</strong>':'<button data-action="accept-daily">รับภารกิจ</button>'}</article>${side}<div class="quest-data-note">รางวัลและความคืบหน้าบันทึกในเครื่องนี้ · Daily ใช้เขตเวลา Asia/Bangkok</div>`);
}
function inventoryPanel(){
  const body=inventoryTab==='bag'?`<div class="inventory-grid">${Object.entries(profile.inventory).filter(([,n])=>n>0).map(([id,n])=>itemCard(id,n)).join('')||'<p class="empty-state">กระเป๋ายังว่าง ลองคุยกับพี่มายาหรือสำรวจสวน</p>'}</div><div class="craft-panel"><h3>Workbench · คราฟต์</h3>${RECIPES.map(recipe=>{const ready=Object.entries(recipe.needs).every(([id,n])=>(profile.inventory[id]||0)>=n);return `<article class="recipe-card"><div><b>${recipe.icon} ${recipe.name}</b><small>${recipe.description}</small><span>ใช้ ${Object.entries(recipe.needs).map(([id,n])=>`${item(id)?.name||id} ×${n}`).join(' + ')}</span></div><button data-action="craft" data-recipe="${recipe.id}" ${ready?'':'disabled'}>${owns(recipe.id)?'คราฟต์เพิ่ม':'คราฟต์'}</button></article>`;}).join('')}</div>`:inventoryTab==='equipment'?`<div class="equipment-slots">${['accessory','tool'].map(slot=>{const equipped=profile.equipped.map(item).find(entry=>entry?.slot===slot);return `<article><span>${slot==='tool'?'อุปกรณ์ฝึก':'เครื่องแต่งกาย'}</span><b>${equipped?`${equipped.icon} ${equipped.name}`:'ช่องว่าง'}</b><small>${equipped?.description||'ใส่ของจากกระเป๋าได้'}</small></article>`;}).join('')}</div><div class="inventory-grid">${Object.entries(profile.inventory).map(([id,n])=>itemCard(id,n)).join('')}</div>`:`<div class="collection-list"><article><b>🦴 Anatomy Notes</b><span>${owns('anatomy-notebook')?`บันทึกตั้งต้น · ${profile.completed.length} เคสที่ผ่าน`:'ยังไม่พบ · รับจากพี่มายา'}</span></article><article><b>👾 Monster Log</b><span>${profile.defeatedMonsters.length}/3 encounters · ${profile.defeatedMonsters.join(', ')||'ยังไม่พบ'}</span></article><article><b>🖼 Image Archive</b><span>${profile.inventory['image-fragment']||0} Image Fragments</span></article><article><b>🏅 Achievements</b><span>${profile.completed.length?'First Exposure · ผ่านเคสแรก ✓':'ผ่านเคสแรกเพื่อปลดล็อก'}</span></article></div>`;
  return windowPanel('STUDENT INVENTORY','กระเป๋าและ collection',`<div class="panel-tabs"><button class="${inventoryTab==='bag'?'active':''}" data-tab="bag">กระเป๋า</button><button class="${inventoryTab==='equipment'?'active':''}" data-tab="equipment">อุปกรณ์</button><button class="${inventoryTab==='collection'?'active':''}" data-tab="collection">สะสม</button></div>${body}`);
}
function skillPanel(){const level=levelForXp(profile.xp);const nodes=SKILLS.map(s=>{const owned=profile.unlockedSkills.includes(s.id),ready=level>=s.level&&s.requires.every(id=>profile.unlockedSkills.includes(id))&&profile.skillPoints>=s.cost;return `<article class="skill-node ${owned?'owned':ready?'available':'locked'}"><span>${s.icon}</span><div><b>${s.name}</b><small>${s.tree} · Lv.${s.level} · ${s.cost} SP</small><p>${s.description}</p><em>${owned?s.effect:s.requires.length?`ต้องมี ${SKILLS.find(p=>p.id===s.requires[0])?.name}`:`ผลจริง: ${s.effect}`}</em></div>${owned?'<strong>✓</strong>':`<button data-action="learn-skill" data-skill="${s.id}" ${ready?'':'disabled'}>เรียน</button>`}</article>`;}).join('');return windowPanel('SKILL TREE','ทักษะการฝึก',`<div class="skill-points"><b>Lv.${level}</b><span>${profile.skillPoints} Skill Points</span><small>ปลดล็อกแต้มละ 1 เมื่อเลเวลเพิ่ม · ${profile.unlockedSkills.length}/${SKILLS.length} ทักษะ</small></div><div class="skill-tree">${['Projection Specialist','Image Analyst','Imaging Engineer','Clinical Explorer'].map(tree=>`<section><h3>${tree}</h3>${SKILLS.filter(s=>s.tree===tree).map(s=>nodes[SKILLS.indexOf(s)]).join('')}</section>`).join('')}</div><p class="skill-note">ทักษะให้คำใบ้และ overlay เพื่อการเรียนรู้ ไม่ใช่การรับรองความสามารถทางคลินิก</p>`);}
function shopPanel(){return windowPanel('NORA · EQUIPMENT SHOP','ร้านอุปกรณ์ฝึก',`<p>เหรียญใช้ซื้อของตกแต่งและอุปกรณ์ช่วยเรียนรู้ · ไม่มีของเพิ่มคะแนนโดยอัตโนมัติ</p><div class="shop-balance">ยอดคงเหลือ <b>🪙 ${profile.coins}</b></div><div class="shop-grid">${ITEMS.filter(i=>i.price).map(i=>`<article class="shop-card"><span>${i.icon}</span><b>${i.name}</b><small>${i.description}</small><em>${i.price} coins</em><button data-action="buy-item" data-item="${i.id}" ${profile.coins<i.price!?'disabled':''}>${owns(i.id)?'ซื้อเพิ่ม':'ซื้อ'}</button></article>`).join('')}</div>`);}
function worldMapPanel(){return windowPanel('RADIANT CITY · FIELD MAP','แผนที่พื้นที่',`<div class="zone-grid">${ZONES.map(z=>`<article class="zone-card ${z.status}"><span>${z.icon}</span><b>${z.name}</b><small>${z.level}</small><p>${z.description}</p>${z.id==='academy'?'<strong>กำลังสำรวจ</strong>':z.id==='noise-lab'?`<button data-action="enter-dungeon" ${profile.questStep>=5?'':'disabled'}>${profile.questStep>=5?'เข้า Noise Laboratory':'ทำ First Exposure ก่อน'}</button>`:'<strong>ยังไม่เปิดใน build นี้</strong>'}</article>`).join('')}</div><p class="quest-data-note">แผนที่ขยายตามเนื้อหาที่เล่นได้จริง พื้นที่ที่ยังพัฒนาจะไม่แสดงเป็นด่านพร้อมเล่น</p>`);}
function worldScreen(){
  const menu=view!=='hub'&&view!=='dungeon';
  let panel='';
  if(view==='library')panel=questPanel();
  if(view==='skills')panel=skillPanel();
  if(view==='inventory')panel=inventoryPanel();
  if(view==='shop')panel=shopPanel();
  if(view==='world-map')panel=worldMapPanel();
  if(view==='learn')panel=`<section class="rpg-window modal-window"><button class="window-close" data-view="hub">×</button><span class="pixel-kicker">LEARNING CENTER</span><h2>มุมเรียนรู้</h2><div class="pixel-book"><b>ฝึกตามลำดับ</b><p>ตรวจตัวตนผู้ป่วยจำลอง → จัดท่า → กำหนดขอบเขตภาพ → ตรวจเทคนิค → ประเมินภาพสังเคราะห์</p></div><div class="pixel-book"><b>หลักความปลอดภัย</b><p>แบบฝึกนี้ใช้ข้อมูลสมมติเท่านั้น ปฏิบัติตามผู้สอนและแนวทางของสถานพยาบาลเสมอ ค่าที่เห็นเป็นหน่วย SIM ไม่ใช่ protocol</p></div><a href="https://www.fda.gov/radiation-emitting-products/medical-imaging/medical-x-ray-imaging" target="_blank" rel="noreferrer">FDA · Medical X-ray Imaging ↗</a><button class="pixel-button" data-view="hub">กลับเข้าเกม</button></section>`;
  if(view==='results')panel=windowPanel('STUDENT RECORD','บันทึกการฝึก',`<div class="rpg-stats"><div><b>${profile.xp}</b><small>EXP</small></div><div><b>${profile.coins}</b><small>COINS</small></div><div><b>Lv.${levelForXp(profile.xp)}</b><small>RANK · ${rankForScore(profile.bestScores[CASES[0].id]||0)}</small></div></div><div class="quest-log-row"><b>เคสที่ผ่าน</b><span>${profile.completed.length}/${CASES.length}</span></div><div class="quest-log-row"><b>เควสต์เสริม</b><span>${profile.completedQuests.length}</span></div><div class="quest-log-row"><b>ดันเจียน</b><span>${profile.completedQuests.includes('noise-lab-clear')?'Noise Lab ✓':'ยังไม่เคลียร์'}</span></div><div class="quest-log-row"><b>ความสัมพันธ์ทีม</b><span>${Object.entries(profile.relationships).map(([name,value])=>`${name} ${value}`).join(' · ')||'คุยกับทีมเพื่อเพิ่มความคุ้นเคย'}</span></div>`);
  const text=dialogueKind==='mentor'?'วันนี้มีเคส Chest X-ray เข้ามา ลองไปเตรียมตัวดูนะ':dialogueKind==='reception'?'มีใบส่งตรวจจำลองสำหรับเคสแรก ตรวจข้อมูลให้ครบก่อนเข้าห้องนะ':dialogueKind==='radiologist'?'ภาพทุกภาพควรได้รับการประเมินตามโจทย์และข้อเสนอแนะจากผู้สอน':dialogueKind==='radiology-door'?'ห้องตรวจพร้อมแล้ว ตรวจรายการรับเคสก่อนเริ่มฝึก':dialogueKind==='no-one'?'เดินเข้าไปใกล้ตัวละครหรือประตู แล้วกด E เพื่อโต้ตอบ':'ยินดีต้อนรับสู่แผนกรังสี! เดินไปพบพี่มายาเพื่อรับภารกิจแรกนะ';
  const interactLabel=profile.questStep===0?'[E] คุยกับพี่มายา':profile.questStep===1?'[E] รับใบส่งตรวจ':profile.questStep===2?'[E] เข้าห้อง X-ray':profile.questStep===3?'[E] ไปประเมินภาพ':'[E] คุยกับทีม';
  worldShell(`<section class="hospital-world ${menu?'world-dimmed':''}"><div id="game-world" class="world-canvas"></div><div class="world-vignette"></div>
    <header class="rpg-hud"><div class="player-card"><img src="${base}assets/student-portrait.png" alt="นักศึกษารังสีเทคนิค"/><div class="player-stats"><b>Lv.${levelForXp(profile.xp)} &nbsp; Radiography Student</b><div class="exp-label">EXP <span>${profile.xp%100} / 100</span></div><div class="exp-track"><i style="width:${profile.xp%100}%"></i></div></div></div><div class="hud-right"><div class="heart-counter"><span>♥</span><b>${profile.hp}</b></div><div class="coin-counter"><i>✦</i><b>${profile.coins}</b></div><button class="pixel-gear" data-view="results" title="บันทึกการฝึก">⚙</button></div></header>
    <aside class="main-quest rpg-window"><div class="quest-title"><span class="quest-glyph">▤</span><b>Main Mission</b></div><div class="quest-step"><i></i><span>${profile.questStep>=5?'เควสต์แรกสำเร็จแล้ว':questObjective()}</span></div><div class="quest-mini-progress"><i style="width:${Math.min(100,profile.questStep*20)}%"></i></div></aside>
    <aside class="hospital-map rpg-window"><b>Hospital Map</b><div class="map-grid"><i class="map-building"></i><i class="map-garden"></i><i class="map-walk"></i><i class="map-pin">◆</i></div></aside>
    <div class="world-controls"><span>WASD / ← ↑ ↓ → เดิน</span><span><kbd>E</kbd> โต้ตอบ</span></div>
    <div class="touch-pad"><button data-move="up" aria-label="เดินขึ้น">▲</button><div><button data-move="left" aria-label="เดินซ้าย">◀</button><button data-move="down" aria-label="เดินลง">▼</button><button data-move="right" aria-label="เดินขวา">▶</button></div><button class="touch-interact" data-action="touch-interact" aria-label="${interactLabel}" title="${interactLabel}">E</button></div>
    <nav class="rpg-dock"><button data-view="inventory"><span class="dock-icon">▣</span><b>Bag</b></button><button data-view="library"><span class="dock-icon">⚑</span><b>Quest</b></button><button data-view="skills"><span class="dock-icon">★</span><b>Skills</b></button><button data-view="world-map"><span class="dock-icon">⌖</span><b>Map</b></button></nav>
    ${view==='dungeon'?'':`<aside class="mentor-dialog rpg-window"><img src="${base}assets/mentor-portrait.png" alt="พี่มายา"/><div><b>${dialogueName}</b><p>${dialogueKind==='welcome'?text:dialogueText||text}</p>${dialogueKind==='mentor'&&profile.questStep===0?'<button class="dialogue-action" data-action="accept-quest">รับเควสต์ · FIRST DAY →</button>':''}${dialogueKind==='reception'&&profile.questStep===1?'<button class="dialogue-action" data-action="accept-referral">รับใบส่งตรวจ →</button>':''}${dialogueKind==='radiology-door'&&profile.questStep>=2&&profile.questStep<4?`<button class="dialogue-action" data-start="${activeCase.id}">เข้าเคส Chest PA →</button>`:''}<button class="dialogue-next" data-action="close-dialogue">▼</button></div></aside>`}
    ${view==='dungeon'?`<aside class="dungeon-objective rpg-window"><b>NOISE LABORATORY</b><span>${profile.completedQuests.includes('noise-lab-clear')?'พบทางออกทางซ้ายแล้ว':'สำรวจห้องและกด E เพื่อวิเคราะห์สิ่งรบกวน'}</span><small>เคสและศัตรูเป็นแบบจำลองเพื่อการเรียนรู้</small></aside>`:''}
    ${encounter&&view==='dungeon'?`<div class="game-modal-shade"><section class="rpg-window interaction-modal battle-panel"><span class="pixel-kicker">${encounter.enemy.boss?'BOSS ENCOUNTER':'KNOWLEDGE ENCOUNTER'}</span><h2>${encounter.enemy.name}</h2><div class="battle-hp"><span>HP</span><i><b style="width:${Math.max(0,encounter.enemy.hp/encounter.enemy.maxHp*100)}%"></b></i><strong>${encounter.enemy.hp}/${encounter.enemy.maxHp}</strong><span>♥ ${profile.hp}</span></div>${encounter.question.topic==='motion'&&profile.unlockedSkills.includes('motion-detection')?'<div class="skill-hint">Motion Detection · เปรียบเทียบขอบซ้อนก่อนเลือก</div>':''}${encounter.question.topic==='noise'&&profile.unlockedSkills.includes('anatomy-scan')?'<div class="skill-hint">Anatomy Scan · ตรวจรูปแบบก่อนตัดสินใจ</div>':''}<p>${encounter.question.question}</p>${!combatFeedback?`<div class="battle-skills">${(profile.unlockedSkills.includes('noise-detection')||profile.equipped.includes('noise-detector'))?`<button data-action="arm-noise" class="${combatSkillActive==='noise-detection'?'active':''}">⌁ Noise Detection ${combatSkillActive==='noise-detection'?'พร้อมใช้':'เตรียมสแกน'}</button>`:''}${profile.unlockedSkills.includes('anatomy-scan')?`<button data-action="arm-anatomy" class="${combatSkillActive==='anatomy-scan'?'active':''}">◉ Anatomy Scan</button>`:''}</div>`:''}<div class="battle-choices">${combatFeedback?`<p class="${combatCorrect?'correct':'incorrect'}">${combatFeedback}</p>`:encounter.question.choices.map((choice,index)=>`<button data-action="combat-answer" data-choice="${index}">${choice}</button>`).join('')}${combatFeedback?'<button class="pixel-button" data-action="combat-continue">ต่อสู้ต่อ →</button>':''}</div><small>เลือกคำตอบเพื่อใช้ทักษะวิเคราะห์ · ตอบผิดเรียนรู้แล้วลองใหม่ได้${profile.unlockedSkills.includes('critical-thinking')?' · Critical Thinking ป้องกัน HP เกม':' · เกมไม่เก็บข้อมูลคนไข้จริง'}</small></section></div>`:''}
    ${panel}${menu?'<button class="modal-backdrop" data-view="hub" aria-label="ปิดหน้าต่าง"></button>':''}
  </section>`);
}
function missionStage(){
  const showX=Boolean(xray);
  worldShell(`<section class="xray-game-screen"><div id="game-world" class="mission-world"></div><div class="mission-glow"></div>
    <header class="mission-hud"><div class="player-card"><img src="${base}assets/student-portrait.png" alt="นักศึกษารังสีเทคนิค"/><div class="player-stats"><b>Lv.${Math.floor(profile.xp/100)+1} &nbsp; Radiography Student</b><div class="exp-label">EXP <span>${profile.xp%100} / 100</span></div><div class="exp-track"><i style="width:${profile.xp%100}%"></i></div></div></div><div class="mission-banner rpg-window"><span class="quest-glyph">☼</span><div><b>Mission: Take a Chest X-Ray</b><div class="mission-pips">${[0,1,2,3,4].map(i=>`<i class="${i<=step?'complete':''}"></i>`).join('')}</div></div></div><div class="hud-right"><div class="heart-counter"><span>♥ ♥ ♥</span></div><div class="coin-counter"><i>✦</i><b>${profile.coins}</b></div><button class="pixel-gear" data-view="hub" title="กลับแผนก">⚙</button></div></header>
    <aside class="mission-checklist rpg-window"><div class="mission-check-title">MISSION CHECKLIST</div>${checklist()}</aside>
    <aside class="mission-preview rpg-window"><div class="preview-title">${showX?'Image Review':'Image Preview'}</div><div class="preview-art ${scanActive?'scan-active':''}">${showX?`<img src="data:image/svg+xml,${encodeURIComponent(xray)}" alt="ภาพ X-ray สังเคราะห์เพื่อการฝึกเท่านั้น"/>${scanActive?`<div class="anatomy-scan-overlay ${scanActive}"><i></i><b>${scanActive==='noise'?'NOISE DETECTION':'ANATOMY SCAN'} · SIM</b></div>`:''}`:'<div class="preview-empty"><span>✧</span><b>ภาพรอการจำลอง</b></div>'}</div>${score?`<div class="preview-score">QUALITY SIM <b>${score.total}/100 · RANK ${rankForScore(score.total)}</b></div>`:''}${showX&&profile.unlockedSkills.includes('anatomy-scan')?`<button class="scan-button" data-action="anatomy-scan">${scanActive==='anatomy'?'ปิด Anatomy Scan':'⌁ Anatomy Scan'}</button>`:''}${showX&&profile.unlockedSkills.includes('noise-detection')?`<button class="scan-button" data-action="noise-scan">${scanActive==='noise'?'ปิด Noise Detection':'⌁ Noise Detection'} ${profile.equipped.includes('noise-detector')?'· DEVICE READY':'· SKILL'}</button>`:''}<div class="preview-tip"><b>✦ Tip!</b><p>${activeCase.hint}</p>${profile.unlockedSkills.includes('detector-awareness')?'<small>DETECTOR INSIGHT SIM · เทียบความคมชัดและ noise ตามโจทย์</small>':''}</div></aside>
    <div class="mission-back"><button data-view="hub">← ออกจากห้องตรวจ</button><span>XR ROOM 01 · ${activeCase.short}</span></div>
    <div class="mentor-speech"><img src="${base}assets/mentor-portrait.png" alt="พี่มายา"/><div class="speech-bubble"><b>MAYA · MENTOR</b><p>${showX?'ตรวจภาพจำลอง แล้วทบทวนคุณภาพตาม checklist นะ':'ตั้งค่าการฝึกและกด EXPOSE เมื่อพร้อมนะ'} <span class="heart-pink">♥</span></p></div></div>
    ${showX?`<div class="mission-review">${reviewPanel()}</div>`:techniqueConsole()}${miniGamePanel()}
    <div class="world-safety">SIMULATION ONLY · NOT FOR DIAGNOSIS OR CLINICAL USE</div>
  </section>`);
}
function techniqueConsole(){return `<section class="tech-panel panel"><div class="tech-heading"><div><span class="eyebrow">SIMULATED TECHNIQUE CONSOLE</span><h2>Set the right technique <small>ค่าจำลองสำหรับเกม</small></h2></div><span class="sim-badge">SIM</span></div><div class="tech-controls"><label class="stepper"><span>kVp <i>SIM</i></span><div><button data-adjust="kvp:-5">−</button><b>${technique.kvp}</b><button data-adjust="kvp:5">+</button></div><small>simulation only</small></label><label class="stepper"><span>mA <i>SIM</i></span><div><button data-adjust="ma:-5">−</button><b>${technique.ma}</b><button data-adjust="ma:5">+</button></div><small>SIM current</small></label><label class="stepper"><span>Time <i>SIM</i></span><div><button data-adjust="time:-0.02">−</button><b>${technique.time.toFixed(2)}<small>s</small></b><button data-adjust="time:0.02">+</button></div><small>SIM duration</small></label><label class="stepper"><span>SID <i>SIM</i></span><div><button data-adjust="sid:-10">−</button><b>${technique.sid}<small>cm</small></b><button data-adjust="sid:10">+</button></div><small>SIM distance</small></label><div class="mas-output"><span>mAs SIM</span><b>${(technique.ma*technique.time).toFixed(2)}</b><small>mA × time</small></div><button class="expose-btn ${verified&&positioned&&collimated?'ready':''}" data-action="expose"><span>☢</span><b>EXPOSE</b><small>SIMULATION</small></button></div><div class="advanced-row"><span class="eyebrow">ADVANCED SIM</span><label><input type="checkbox" data-toggle="grid" ${technique.grid?'checked':''}/> Grid SIM</label><label><input type="checkbox" data-toggle="aec" ${technique.aec?'checked':''}/> AEC SIM</label><span class="oid-control">OID SIM <button data-adjust="oid:-2">−</button><b>${technique.oid} cm</b><button data-adjust="oid:2">+</button></span><span class="mas-equation">mAs = mA × time</span></div><div class="tech-notice">หน่วย SIM สมมติเท่านั้น · ไม่ใช่ protocol ทางคลินิก</div></section>`;}
function miniGamePanel(){
  if(miniGame==='positioning')return `<div class="game-modal-shade"><section class="rpg-window interaction-modal"><button class="window-close" data-action="close-minigame">×</button><span class="pixel-kicker">POSITIONING MINI-GAME</span><h2>จัดท่าผู้ป่วยจำลอง</h2><p>เลือก projection จัดลำตัวให้อยู่กึ่งกลาง และเลือกท่าแขนตามโจทย์จำลอง</p>${profile.unlockedSkills.includes('positioning-insight')?'<div class="skill-hint">Positioning Insight · จัดกึ่งกลางแล้วเลือกท่าแขนตามโจทย์</div>':''}<div class="projection-picks">${['PA','AP','Lateral'].map(p=>`<button class="${positionChoice===p?'chosen':''}" data-projection="${p}">${p}</button>`).join('')}</div><div class="position-board"><div class="position-target"></div>${profile.unlockedSkills.includes('center-guide')?'<div class="center-guide">✚</div>':''}<div class="position-patient ${poseChoice==='clinical'?'pose-clinical':''}" style="transform:translateX(${(patientOffset-2)*18}px)"><i></i><b></b><span class="patient-arm arm-left"></span><span class="patient-arm arm-right"></span><span class="patient-leg leg-left"></span><span class="patient-leg leg-right"></span></div></div><div class="pose-actions"><button class="${poseChoice==='clinical'?'chosen':''}" data-pose="clinical">✦ วางแขนตามโจทย์</button><button class="${poseChoice==='rest'?'chosen':''}" data-pose="rest">พักแขน</button></div><div class="position-nudge"><button data-action="position-left">← เลื่อน</button><span>${patientOffset===2?'CENTERED':'ปรับกึ่งกลาง'}</span><button data-action="position-right">เลื่อน →</button></div>${timingMessage?`<p class="mini-feedback">${timingMessage}</p>`:''}<button class="pixel-button" data-action="confirm-position">ยืนยันการจัดท่า</button></section></div>`;
  if(miniGame==='collimation')return `<div class="game-modal-shade"><section class="rpg-window interaction-modal"><button class="window-close" data-action="close-minigame">×</button><span class="pixel-kicker">COLLIMATION MINI-GAME</span><h2>กำหนดขอบเขตภาพ</h2><p>เลือก field ที่ครอบคลุมบริเวณโจทย์และจำกัดพื้นที่ที่ไม่จำเป็นในแบบจำลอง</p>${profile.unlockedSkills.includes('collimation-focus')?'<div class="skill-hint">Collimation Focus · ใช้กรอบสีเขียวเทียบกับบริเวณโจทย์</div>':''}<div class="collimation-board"><div class="field-box ${collimationChoice}"><span>CHEST SIM FIELD</span></div><div class="field-anatomy">✦ · LUNG AREA SIM · ✦</div></div><div class="projection-picks">${[['tight','แคบเกินไป'],['optimal','เหมาะกับโจทย์'],['wide','กว้างเกินไป']].map(([k,label])=>`<button class="${collimationChoice===k?'chosen':''}" data-collimation="${k}">${label}</button>`).join('')}</div>${timingMessage?`<p class="mini-feedback">${timingMessage}</p>`:''}<button class="pixel-button" data-action="confirm-collimation">ยืนยันขอบเขต</button></section></div>`;
  if(miniGame==='timing')return `<div class="game-modal-shade"><section class="rpg-window interaction-modal timing-modal"><button class="window-close" data-action="close-minigame">×</button><span class="pixel-kicker">BREATHING & EXPOSURE TIMING</span><h2>ฟังคำแนะนำผู้ป่วย</h2><p>“หายใจเข้าลึก ๆ … กลั้นหายใจไว้เมื่อพร้อมนะ” กดปุ่มตอน marker อยู่ในแถบสีเขียว</p><div class="timing-track"><i></i><b></b><em></em></div><div class="timing-caption"><span>หายใจ</span><span>กลั้นหายใจ</span><span>หายใจ</span></div>${timingMessage?`<p class="mini-feedback">${timingMessage}</p>`:''}<button class="expose-btn timing-trigger" data-action="timing-fire"><span>☢</span><b>EXPOSE NOW</b></button></section></div>`;
  return '';
}
function hub(){const next=CASES.find(c=>!profile.completed.includes(c.id))||CASES[0];appShell('hub',`<section class="hero-grid"><div class="welcome-card panel"><div class="eyebrow">✦ YOUR FIRST SHIFT STARTS HERE</div><h1>Every image tells<br><em>a story.</em></h1><p>เรียนรู้การถ่ายภาพรังสีผ่านภารกิจจำลอง<br>ฝึกคิดเป็นขั้นตอน ในพื้นที่ปลอดภัย</p><div class="hero-actions"><button class="primary" data-start="${next.id}">เริ่มภารกิจ <span>→</span></button><button class="secondary" data-view="library">ดูเคสทั้งหมด</button></div><div class="welcome-stats"><span><b>${profile.completed.length}</b> CASES COMPLETE</span><span><b>${profile.xp}</b> TOTAL XP</span><span><b>${profile.missions}</b> EXPOSURES</span></div><div class="sticker sticker-one">✦</div><div class="sticker sticker-two">☼</div></div><div class="mentor-card panel"><div class="mentor-spark">✦</div><div class="mentor-avatar">👩🏻‍⚕️</div><div class="mentor-copy"><span class="eyebrow">MENTOR · MAYA</span><p>“พร้อมเริ่มเวรแรกหรือยัง? เราจะค่อย ๆ ฝึกไปด้วยกันนะ”</p><button data-view="learn" class="text-button">รู้จักการฝึกนี้ <span>↗</span></button></div><div class="speech-tail"></div></div></section><section class="home-lower"><div class="section-heading"><div><span class="eyebrow">YOUR TRAINING PATH</span><h2>เส้นทางฝึกของคุณ</h2></div><button data-view="library" class="text-button">ดูทั้งหมด →</button></div><div class="path-card panel"><div class="path-art"><div class="path-sun">☀</div><div class="path-mountain"></div><span>01</span></div><div class="path-info"><span class="badge">${profile.completed.includes(next.id)?'REPLAY AVAILABLE':'NEXT MISSION'}</span><h3>${next.title} <small>${next.short}</small></h3><p>${next.objective}</p><div class="path-progress"><i style="width:${profile.completed.includes(next.id)?'100':'18'}%"></i></div><div class="path-meta"><span>◷ 5–8 MIN</span><span>✦ BEGINNER</span></div></div><button class="path-play" data-start="${next.id}">เริ่ม <b>→</b></button></div><div class="quick-cards"><button class="quick-card panel" data-view="library"><span class="quick-icon blue">▦</span><span><b>คลังภารกิจ</b><small>สำรวจโจทย์ฝึกทั้งหมด</small></span><i>→</i></button><button class="quick-card panel" data-view="learn"><span class="quick-icon gold">✧</span><span><b>มุมเรียนรู้</b><small>ทบทวนแนวคิดพื้นฐาน</small></span><i>→</i></button></div></section>`);}
function checklist(){return `<div class="checklist panel"><div class="check-title">MISSION CHECKLIST <small>${['01','02','03','04'][step]||'04'} / 04</small></div><button class="check-row ${verified?'done':''}" data-step="verify"><span>${verified?'✓':'□'}</span><b>VERIFY PATIENT</b></button><button class="check-row ${positioned?'done':''}" data-step="position"><span>${positioned?'✓':'□'}</span><b>POSITION</b></button><button class="check-row ${collimated?'done':''}" data-step="collimate"><span>${collimated?'✓':'□'}</span><b>COLLIMATE</b></button><div class="check-note">${step===0?'เริ่มจากยืนยันตัวตนผู้ป่วยจำลอง':step===1?'เลือกท่าตามโจทย์และจัดตำแหน่ง':step===2?'กำหนดขอบเขตภาพจำลอง':step===3?'ตรวจการตั้งค่าแล้วกด EXPOSE!':'ตรวจภาพและทบทวนผล'}</div></div>`;}
function mission(){const showX=Boolean(xray);appShell('mission',`<section class="mission-top"><button class="back-link" data-view="hub">← กลับ Lobby</button><div class="mission-title"><span class="eyebrow">TRAINING MISSION · ${activeCase.short}</span><h1>${activeCase.title}</h1></div><div class="mission-progress"><span>MISSION PROGRESS</span><div>${[0,1,2,3,4].map((n)=>`<i class="${n<=step?'lit':''}"></i>`).join('')}</div></div></section><section class="sim-layout"><div class="room-column"><div class="room-frame panel"><div id="game-world" class="game-world"></div><div class="room-label"><span class="live-dot"></span> SIM ROOM 01 <span>·</span> ${activeCase.view}</div><div class="room-callout">${showX?'ภาพจำลองพร้อมแล้ว · ไปที่ Image review':'TRAINING ROOM · CHEST RADIOGRAPHY'}</div></div><div class="room-bottom"><div class="mentor-mini"><div class="mini-face">👩🏻‍⚕️</div><div><small>MAYA · MENTOR</small><p>${showX?'“ลองดูภาพแล้วสังเกตขอบเขตและความคมชัดนะ”':'“ค่อย ๆ ทำทีละขั้น แล้วตรวจเช็กลิสต์ก่อนเปิดรับภาพนะ”'}</p></div></div><div class="patient-tag panel"><span class="patient-icon">☺</span><span><small>SIM PATIENT</small><b>Case ${String(CASES.indexOf(activeCase)+1).padStart(2,'0')} · Alex R.</b></span><span class="patient-state">${verified?'VERIFIED':'WAITING'}</span></div></div></div><aside class="side-column">${checklist()}<div class="xray-card panel"><div class="xray-head"><b>${showX?'Image Review':'Image Preview'}</b><span>${showX?'SIM':'READY'}</span></div><div class="xray-window">${showX?`<img alt="ภาพเอกซเรย์ทรวงอกสังเคราะห์สำหรับการฝึกเท่านั้น" src="data:image/svg+xml,${encodeURIComponent(xray)}"/>`:`<div class="xray-placeholder"><span>✧</span><b>ภาพจะปรากฏที่นี่</b><small>หลังเริ่ม Exposure จำลอง</small></div>`}</div>${score?`<div class="score-strip"><span>IMAGE QUALITY</span><b>${score.total}<small>/100</small></b></div>`:''}<div class="tip-box"><span>☼</span><div><b>TIP · TRAINING ONLY</b><p>${activeCase.hint}</p></div></div></div><div class="objective-card panel"><span class="eyebrow">CASE OBJECTIVE</span><p>${activeCase.objective}</p><small>ANATOMY · ${activeCase.anatomy}</small></div></aside></section>${showX?reviewPanel():techniquePanel()}`);}
function techniquePanel(){return `<section class="tech-panel panel"><div class="tech-heading"><div><span class="eyebrow">SIMULATED TECHNIQUE CONSOLE</span><h2>Set the right technique <small>ปรับค่าเพื่อการเรียนรู้</small></h2></div><span class="sim-badge">SIM UNITS</span></div><div class="tech-controls"><label class="stepper"><span>kVp <i>SIM</i></span><div><button data-adjust="kvp:-5">−</button><b>${technique.kvp}</b><button data-adjust="kvp:5">+</button></div><small>Energy setting · educational</small></label><label class="stepper"><span>mAs <i>SIM</i></span><div><button data-adjust="mas:-0.5">−</button><b>${technique.mas.toFixed(1)}</b><button data-adjust="mas:0.5">+</button></div><small>Exposure quantity · educational</small></label><label class="stepper"><span>SID <i>SIM</i></span><div><button data-adjust="sid:-10">−</button><b>${technique.sid}<small>cm</small></b><button data-adjust="sid:10">+</button></div><small>Source-to-image distance · SIM</small></label><label class="stepper"><span>Time <i>SIM</i></span><div><button data-adjust="time:-0.02">−</button><b>${technique.time.toFixed(2)}<small>s</small></b><button data-adjust="time:0.02">+</button></div><small>Simulated exposure time</small></label><button class="expose-btn ${positioned?'ready':''}" data-action="expose"><span>☢</span><b>EXPOSE</b><small>SIMULATION</small></button></div><div class="advanced-row"><span class="eyebrow">ADVANCED SIM OPTIONS</span><label><input type="checkbox" data-toggle="grid" ${technique.grid?'checked':''}/> Grid SIM</label><label><input type="checkbox" data-toggle="aec" ${technique.aec?'checked':''}/> AEC SIM</label><span class="mas-equation">mAs SIM = mA SIM × time SIM</span></div><div class="tech-notice">ค่าทั้งหมดเป็นหน่วยสมมติเพื่อการเรียนรู้เท่านั้น ไม่ใช่โปรโตคอลหรือคำแนะนำทางคลินิก</div></section>`;}
function reviewPanel(){return `<section class="review-panel panel"><div><span class="eyebrow">MISSION DEBRIEF · RANK ${rankForScore(score!.total)} · GAME ONLY</span><h2>${score!.total>=80?'ทำได้ดีมาก! ภาพฝึกพร้อมทบทวน':'ภารกิจเสร็จแล้ว · มาเรียนรู้จากผลกัน'}</h2><p>ผลคะแนนคำนวณเพื่อเกมและการเรียนรู้เท่านั้น · ไม่ใช่การประเมินสมรรถนะทางคลินิก</p></div>${profile.unlockedSkills.includes('image-critique')?'<div class="skill-hint">Image Critique · ตรวจ coverage, sharpness, contrast และ positioning แยกกัน</div>':''}<div class="score-bars">${[['Contrast SIM',score!.contrast],['Coverage SIM',score!.coverage],['Sharpness SIM',score!.sharpness],['Positioning',score!.positioning]].map(([k,v])=>`<div><span>${k}</span><i><b style="width:${v}%"></b></i><strong>${v}</strong></div>`).join('')}</div>${profile.unlockedSkills.includes('image-optimization')?`<div class="optimization-note">Image Optimization SIM · ${score!.total>=80?'ภาพรวมอยู่ในช่วงดีของแบบฝึก':'เลือกหมวดคะแนนต่ำสุดหนึ่งข้อเพื่อทบทวน'} · แนวโน้มไม่ใช่เกณฑ์วินิจฉัย</div>`:''}${profile.unlockedSkills.includes('protocol-memory')?'<p class="protocol-note">Protocol Memory · ย้อนอ่านโจทย์และคำใบ้ใน Learning Center ได้ทุกเมื่อ</p>':''}<ul>${score!.notes.map(n=>`<li>${n}</li>`).join('')}</ul><div class="review-actions"><button class="secondary" data-action="retry">${profile.unlockedSkills.includes('fast-workflow')?'เริ่มเคสซ้ำแบบย่อ →':'ลองอีกครั้ง'}</button><button class="primary" data-view="hub">กลับ Lobby →</button><button class="text-button" data-view="learn">อ่านแนวคิดพื้นฐาน ↗</button></div></section>`;}
function library(){appShell('library',`<section class="page-intro"><span class="eyebrow">TRAINING CASE FILES</span><h1>เลือกโจทย์ฝึก <em>ของคุณ</em></h1><p>แต่ละเคสเป็นสถานการณ์สมมติ เริ่มจากพื้นฐานแล้วค่อย ๆ ปลดล็อกโจทย์ถัดไป</p></section><section class="case-grid">${CASES.map((c,i)=>`<article class="case-card panel ${unlocked(c)?'':'locked'}"><div class="case-art art-${i}"><span>${['胸','◫','✋','⌁','◉'][i]}</span><small>SIM CASE · ${String(i+1).padStart(2,'0')}</small>${!unlocked(c)?'<b class="lock">🔒</b>':''}</div><div class="case-content"><span class="badge">${unlocked(c)?(profile.completed.includes(c.id)?'COMPLETED':'AVAILABLE'):'LOCKED'}</span><h2>${c.title}</h2><p>${c.objective}</p><div class="case-foot"><span>${c.view}</span>${unlocked(c)?`<button data-start="${c.id}">${profile.completed.includes(c.id)?'เล่นซ้ำ':'เริ่มฝึก'} →</button>`:`<small>ผ่าน ${c.unlockedAt} ภารกิจก่อนหน้า</small>`}</div></div></article>`).join('')}</section><div class="library-note panel"><b>✦ ปลดล็อกโจทย์ถัดไป</b><span>ทำภารกิจให้เสร็จเพื่อเปิดเคสใหม่ ความคืบหน้าบันทึกไว้ในอุปกรณ์นี้</span></div>`);}
function learn(){appShell('learn',`<section class="page-intro"><span class="eyebrow">LEARNING CORNER · SIMULATION GUIDE</span><h1>ฝึกคิดอย่าง <em>ปลอดภัย</em></h1><p>เกมนี้เป็นสื่อการเรียนรู้เบื้องต้น ไม่ใช้แทนการสอน การกำกับดูแล หรือแนวทางปฏิบัติของสถานพยาบาล</p></section><section class="learn-grid"><article class="learn-card panel"><div class="learn-icon">☑</div><span class="eyebrow">01 · BEFORE EXPOSURE</span><h2>เริ่มจากผู้ป่วยและโจทย์</h2><p>ฝึกตรวจสอบข้อมูลผู้ป่วยจำลอง ทบทวนคำขอ ตรวจการจัดท่า และทำตามขั้นตอนความปลอดภัยที่ผู้สอนกำหนด</p><div class="learn-rule">JUSTIFY <i>→</i> OPTIMIZE <i>→</i> REVIEW</div></article><article class="learn-card panel"><div class="learn-icon gold">◉</div><span class="eyebrow">02 · IMAGE FORMATION</span><h2>ปรับทีละตัวแปร</h2><p>ในการจำลองนี้ kVp, mAs และระยะทางมีผลต่อภาพที่สร้างขึ้นเพื่อให้เห็นแนวคิดเชิงคุณภาพ ตัวเลขในเกมไม่ใช่ค่าใช้งานจริง</p><div class="learn-rule">OBSERVE <i>→</i> ADJUST <i>→</i> COMPARE</div></article><article class="learn-card panel"><div class="learn-icon mint">☼</div><span class="eyebrow">03 · SAFETY MINDSET</span><h2>คำนึงถึงความเหมาะสม</h2><p>แนวคิดการป้องกันรังสีสำหรับการเรียนรู้เน้นความเหมาะสมและการลดการรับรังสีโดยไม่จำเป็น ภายใต้การดูแลของผู้มีคุณสมบัติ</p><div class="learn-rule">ALARA · LEARN WITH CARE</div></article><article class="learn-card source-card panel"><span class="eyebrow">อ่านเพิ่มเติมจากแหล่งทางการ</span><h2>เรียนรู้อย่างมีแหล่งอ้างอิง</h2><p>ข้อมูลในเกมย่อเพื่อใช้ประกอบการเรียนรู้ ตรวจสอบรายละเอียดและคำแนะนำล่าสุดจากแหล่งทางการเสมอ</p><a href="https://www.fda.gov/radiation-emitting-products/medical-imaging/medical-x-ray-imaging" target="_blank" rel="noreferrer">FDA · Medical X-ray Imaging ↗</a><a href="https://www.fda.gov/radiation-emitting-products/medical-imaging/radiography" target="_blank" rel="noreferrer">FDA · Radiography ↗</a><a href="https://www-pub.iaea.org/MTCD/Publications/PDF/te_1641_web.pdf" target="_blank" rel="noreferrer">IAEA · Radiation Protection ↗</a></article></section><section class="quiz-card panel"><div><span class="eyebrow">QUICK CHECK · PRACTICE</span><h2>ก่อนกด Exposure จำลอง ควรทำอะไรก่อน?</h2><p>เลือกคำตอบที่ดีที่สุดเพื่อรับ XP เพิ่ม 10 คะแนน (หนึ่งครั้งต่ออุปกรณ์)</p></div><div class="quiz-options"><button data-quiz="wrong">รีบเพิ่มค่าทุกตัวให้สูงที่สุด</button><button data-quiz="correct">ตรวจโจทย์และเช็กลิสต์ให้ครบ</button><button data-quiz="wrong">ข้ามการตรวจผู้ป่วยจำลอง</button></div><div id="quiz-feedback" aria-live="polite"></div></section>`);}
function results(){appShell('results',`<section class="results-card panel"><div class="result-spark">✦</div><span class="eyebrow">YOUR TRAINING LOG</span><h1>ความก้าวหน้า <em>ของคุณ</em></h1><p>ข้อมูลบันทึกไว้เฉพาะในเบราว์เซอร์เครื่องนี้</p><div class="result-stats"><div><b>${profile.xp}</b><span>TOTAL XP</span></div><div><b>${profile.completed.length}/${CASES.length}</b><span>CASES DONE</span></div><div><b>${profile.missions}</b><span>SIM EXPOSURES</span></div></div><button data-view="hub" class="primary">กลับ Lobby →</button><button data-action="reset" class="text-button">เริ่มข้อมูลเกมใหม่</button></section>`);}
function bind(){root.querySelectorAll<HTMLElement>('[data-view]').forEach(el=>el.addEventListener('click',()=>{const v=el.dataset.view as GameView;view=v;render();}));root.querySelectorAll<HTMLElement>('[data-start]').forEach(el=>el.addEventListener('click',()=>startCase(el.dataset.start!)));root.querySelectorAll<HTMLElement>('[data-step]').forEach(el=>el.addEventListener('click',()=>{const s=el.dataset.step;if(s==='verify'){verified=true;step=Math.max(step,1)}if(s==='position'){positioned=true;patientReady=true;step=Math.max(step,2)}if(s==='collimate'){collimated=!collimated;step=Math.max(step,3)}render();}));root.querySelectorAll<HTMLElement>('[data-adjust]').forEach(el=>el.addEventListener('click',()=>{const [k,d]=el.dataset.adjust!.split(':');const key=k as keyof Technique;const ranges:Record<string,[number,number]>={kvp:[60,150],mas:[.5,8],sid:[100,220],time:[.02,.5]};technique[key]=Math.min(ranges[k][1],Math.max(ranges[k][0],Number((Number(technique[key])+Number(d)).toFixed(2)))) as never;render();}));root.querySelectorAll<HTMLInputElement>('[data-toggle]').forEach(el=>el.addEventListener('change',()=>{technique[el.dataset.toggle as 'grid'|'aec']=el.checked;render();}));root.querySelectorAll<HTMLElement>('[data-action]').forEach(el=>el.addEventListener('click',()=>{if(el.dataset.action==='expose')expose();if(el.dataset.action==='retry'){xray='';score=null;step=0;verified=positioned=collimated=breath=patientReady=false;view='mission';render();}if(el.dataset.action==='reset'){localStorage.removeItem(SAVE_KEY);location.reload();}}));root.querySelectorAll<HTMLElement>('[data-quiz]').forEach(el=>el.addEventListener('click',()=>{const f=document.querySelector<HTMLElement>('#quiz-feedback');if(el.dataset.quiz==='correct'){if(!localStorage.getItem('radtech-pixel-quiz')){profile.xp+=10;localStorage.setItem('radtech-pixel-quiz','1');save();}f!.textContent='ถูกต้อง! ตรวจโจทย์และเช็กลิสต์ก่อนเสมอ · +10 XP';}else f!.textContent='ลองทบทวนอีกครั้ง: เริ่มจากโจทย์และความพร้อมของผู้ป่วยจำลอง';f!.className='quiz-feedback';}));}
function bindRpg(){
  root.querySelectorAll<HTMLElement>('[data-view]').forEach(el=>el.addEventListener('click',()=>{view=el.dataset.view as GameView;render();}));
  root.querySelectorAll<HTMLElement>('[data-start]').forEach(el=>el.addEventListener('click',()=>startCase(el.dataset.start!)));
  root.querySelectorAll<HTMLElement>('[data-step]').forEach(el=>el.addEventListener('click',()=>{const key=el.dataset.step;if(key==='verify'){verified=!verified;step=Math.max(step,1)}if(key==='position'){miniGame='positioning';timingMessage='';}if(key==='collimate'){miniGame='collimation';timingMessage='';}render();}));
  root.querySelectorAll<HTMLElement>('[data-adjust]').forEach(el=>el.addEventListener('click',()=>{const [k,d]=el.dataset.adjust!.split(':');const key=k as keyof Technique;const ranges:Record<string,[number,number]>={kvp:[60,150],ma:[10,100],sid:[100,220],oid:[0,40],time:[.02,.5]};technique[key]=Math.min(ranges[k][1],Math.max(ranges[k][0],Number((Number(technique[key])+Number(d)).toFixed(2)))) as never;if(k==='ma'||k==='time')technique.mas=Number((technique.ma*technique.time).toFixed(2));render();}));
  root.querySelectorAll<HTMLElement>('[data-projection]').forEach(el=>el.addEventListener('click',()=>{positionChoice=el.dataset.projection!;render();}));
  root.querySelectorAll<HTMLElement>('[data-pose]').forEach(el=>el.addEventListener('click',()=>{poseChoice=el.dataset.pose!;gameRef?.events.emit('patient-pose',poseChoice);render();}));
  root.querySelectorAll<HTMLElement>('[data-collimation]').forEach(el=>el.addEventListener('click',()=>{collimationChoice=el.dataset.collimation!;render();}));
  root.querySelectorAll<HTMLInputElement>('[data-toggle]').forEach(el=>el.addEventListener('change',()=>{technique[el.dataset.toggle as 'grid'|'aec']=el.checked;render();}));
  root.querySelectorAll<HTMLElement>('[data-tab]').forEach(el=>el.addEventListener('click',()=>{inventoryTab=el.dataset.tab as typeof inventoryTab;render();}));
  root.querySelectorAll<HTMLElement>('[data-action="accept-side"]').forEach(el=>el.addEventListener('click',()=>{const id=el.dataset.quest!;if(!profile.activeQuests.includes(id)&&!profile.completedQuests.includes(id))profile.activeQuests.push(id);save();render();}));
  root.querySelectorAll<HTMLElement>('[data-action="claim-side"]').forEach(el=>el.addEventListener('click',()=>{const quest=SIDE_QUESTS.find(q=>q.id===el.dataset.quest);if(!quest)return;if(awardQuest(quest.id,quest.rewardXp,quest.rewardCoins,quest.rewardItem)){profile.activeQuests=profile.activeQuests.filter(id=>id!==quest.id);render();}}));
  root.querySelectorAll<HTMLElement>('[data-action="buy-item"]').forEach(el=>el.addEventListener('click',()=>{const entry=item(el.dataset.item||'');if(!entry?.price||profile.coins<entry.price)return;profile.coins-=entry.price;grant(entry.id);save();render();}));
  root.querySelectorAll<HTMLElement>('[data-action="craft"]').forEach(el=>el.addEventListener('click',()=>{const recipe=RECIPES.find(r=>r.id===el.dataset.recipe);if(!recipe)return;const canCraft=Object.entries(recipe.needs).every(([id,n])=>(profile.inventory[id]||0)>=n);if(!canCraft)return;for(const [id,n] of Object.entries(recipe.needs))removeItem(profile,id,n);grant(recipe.id);save();render();}));
  root.querySelectorAll<HTMLElement>('[data-action="equip"]').forEach(el=>el.addEventListener('click',()=>{const entry=item(el.dataset.item||'');if(!entry?.slot||!owns(entry.id))return;const equipped=profile.equipped.includes(entry.id);profile.equipped=profile.equipped.filter(id=>item(id)?.slot!==entry.slot);if(!equipped)profile.equipped.push(entry.id);gameRef?.events.emit('player-outfit',profile.equipped.includes('pixel-coat'));save();render();}));
  root.querySelectorAll<HTMLElement>('[data-action="use-item"]').forEach(el=>el.addEventListener('click',()=>{if(removeItem(profile,'medical-supply')){profile.hp=Math.min(profile.maxHp,profile.hp+25);save();render();}}));
  root.querySelectorAll<HTMLElement>('[data-action="learn-skill"]').forEach(el=>el.addEventListener('click',()=>{const skill=SKILLS.find(s=>s.id===el.dataset.skill);if(!skill||profile.unlockedSkills.includes(skill.id)||profile.skillPoints<skill.cost||levelForXp(profile.xp)<skill.level||!skill.requires.every(id=>profile.unlockedSkills.includes(id)))return;profile.skillPoints-=skill.cost;profile.unlockedSkills.push(skill.id);save();render();}));
  root.querySelectorAll<HTMLElement>('[data-action="accept-daily"]').forEach(el=>el.addEventListener('click',()=>{if(!profile.activeQuests.includes(DAILY_QUEST.id)){profile.activeQuests.push(DAILY_QUEST.id);profile.dailyStartMissions=profile.missions;save();render();}}));
  root.querySelectorAll<HTMLElement>('[data-action="claim-daily"]').forEach(el=>el.addEventListener('click',()=>{if(profile.dailyClaimDate===dayKey()||profile.missions<=profile.dailyStartMissions)return;profile.dailyClaimDate=dayKey();profile.activeQuests=profile.activeQuests.filter(id=>id!==DAILY_QUEST.id);grantXp(profile,DAILY_QUEST.rewardXp);profile.coins+=DAILY_QUEST.rewardCoins;grant(DAILY_QUEST.rewardItem!);save();render();}));
  root.querySelectorAll<HTMLElement>('[data-action="arm-noise"],[data-action="arm-anatomy"]').forEach(el=>el.addEventListener('click',()=>{const target=el.dataset.action==='arm-noise'?'noise-detection':'anatomy-scan';combatSkillActive=combatSkillActive===target?'':target;render();}));
  root.querySelectorAll<HTMLElement>('[data-action="combat-answer"]').forEach(el=>el.addEventListener('click',()=>gameRef?.events.emit('combat-answer',Number(el.dataset.choice),combatSkillActive)));
  root.querySelectorAll<HTMLElement>('[data-action="combat-continue"]').forEach(el=>el.addEventListener('click',()=>{combatFeedback='';combatSkillActive='';encounter=null;gameRef?.events.emit('combat-continue');render();}));
  root.querySelectorAll<HTMLElement>('[data-action]').forEach(el=>el.addEventListener('click',()=>{
    const action=el.dataset.action;
    if(action==='touch-interact')return;
    if(action==='enter-dungeon'){enterDungeon();return;}
    if(action==='anatomy-scan'){scanActive=scanActive==='anatomy'?'':'anatomy';render();return;}
    if(action==='noise-scan'){scanActive=scanActive==='noise'?'':'noise';render();return;}
    if(action==='accept-quest'){profile.questStep=1;profile.relationships.Maya=(profile.relationships.Maya||0)+1;if(!profile.activeQuests.includes('first-exposure'))profile.activeQuests.push('first-exposure');dialogueKind='mentor';dialogueName='MAYA · SENIOR TECHNOLOGIST';dialogueText='เริ่มภารกิจแล้ว! ไปที่ Reception เพื่อรับใบส่งตรวจจำลอง แล้วนำไปที่ห้อง X-ray';save();}
    else if(action==='accept-referral'){profile.questStep=2;profile.relationships.Reception=(profile.relationships.Reception||0)+1;dialogueKind='reception';dialogueName='RECEPTION';dialogueText='รับใบส่งตรวจจำลองแล้ว ตรวจรายการให้ครบ จากนั้นเดินไปที่ประตู RADIOLOGY';save();}
    else if(action==='close-dialogue'){dialogueKind='welcome';dialogueText='';}
    else if(action==='touch-interact'){gameRef?.events.emit('virtual-interact');return;}
    else if(action==='inventory'){view='inventory';}
    else if(action==='expose'){expose();return;}
    else if(action==='close-minigame'){miniGame=null;timingMessage='';}
    else if(action==='position-left'){patientOffset=Math.max(0,patientOffset-1);}
    else if(action==='position-right'){patientOffset=Math.min(4,patientOffset+1);}
    else if(action==='confirm-position'){if(positionChoice==='PA'&&patientOffset===2&&poseChoice==='clinical'){positioned=true;patientReady=true;miniGame=null;step=Math.max(step,2);timingMessage='';}else{positioned=false;timingMessage=positionChoice!=='PA'?'โจทย์นี้เป็น Chest PA · เลือก projection ให้ตรงโจทย์':patientOffset!==2?'ผู้ป่วยยังไม่อยู่กึ่งกลาง · ลองเลื่อนแล้วตรวจใหม่':'เลือกท่าผู้ป่วยตามโจทย์ก่อนยืนยัน';}}
    else if(action==='confirm-collimation'){if(collimationChoice==='optimal'){collimated=true;miniGame=null;step=Math.max(step,3);timingMessage='';}else{collimated=false;timingMessage='ลองปรับ field ให้พอดีกับบริเวณโจทย์ โดยไม่แคบหรือกว้างเกินไป';}}
    else if(action==='timing-fire'){fireTiming();return;}
    else if(action==='retry'){xray='';score=null;step=0;verified=positioned=collimated=breath=patientReady=false;view='mission';render();return;}
    else if(action==='reset'){localStorage.removeItem(SAVE_KEY);location.reload();return;}
    render();
  }));
  const interactControl=root.querySelector<HTMLButtonElement>('[data-action="touch-interact"]');
  if(interactControl){
    let held=false;
    const release=()=>{if(!held)return;held=false;window.removeEventListener('pointerup',release);window.removeEventListener('pointercancel',release);window.removeEventListener('blur',release);gameRef?.events.emit('virtual-interact',false);};
    interactControl.addEventListener('pointerdown',(event:PointerEvent)=>{
      if(held)return;
      event.preventDefault();held=true;
      try{interactControl.setPointerCapture(event.pointerId);}catch{}
      gameRef?.events.emit('virtual-interact',true);
      window.addEventListener('pointerup',release);
      window.addEventListener('pointercancel',release);
      window.addEventListener('blur',release);
    });
    interactControl.addEventListener('lostpointercapture',release);
    interactControl.addEventListener('click',(event:MouseEvent)=>{
      if(event.detail!==0)return;
      gameRef?.events.emit('virtual-interact',true);
      requestAnimationFrame(()=>gameRef?.events.emit('virtual-interact',false));
    });
  }
  root.querySelectorAll<HTMLElement>('[data-move]').forEach(el=>{const direction=el.dataset.move!;const down=(event:Event)=>{event.preventDefault();gameRef?.events.emit('virtual-move',direction,true);};const up=(event:Event)=>{event.preventDefault();gameRef?.events.emit('virtual-move',direction,false);};el.addEventListener('pointerdown',down);el.addEventListener('pointerup',up);el.addEventListener('pointerleave',up);el.addEventListener('pointercancel',up);});
}
function startCase(id:string){activeCase=CASES.find(c=>c.id===id&&unlocked(c))||CASES[0];if(profile.questStep===2)profile.questStep=3;view='mission';step=0;verified=positioned=collimated=breath=patientReady=false;score=null;xray='';miniGame=null;positionChoice='PA';patientOffset=2;poseChoice='rest';gameRef?.events.emit('patient-pose','rest');scanActive='';collimationChoice='optimal';technique={kvp:110,ma:31.25,mas:2.5,sid:180,oid:8,time:.08,grid:false,aec:false};save();render();}
function expose(){if(!verified){timingMessage='เริ่มจาก Verify Patient ใน checklist ก่อน';render();return;}if(!positioned){miniGame='positioning';timingMessage='จัดท่าตามโจทย์ก่อนเปิดรับภาพ';render();return;}if(!collimated){miniGame='collimation';timingMessage='ตรวจขอบเขตภาพจำลองก่อนเปิดรับภาพ';render();return;}miniGame='timing';timingStarted=performance.now();timingMessage='';render();}
function fireTiming(){const phase=(performance.now()-timingStarted)%1800,calm=profile.unlockedSkills.includes('calm-focus'),start=calm?630:720,end=calm?1420:1330;if(phase<start||phase>end){timingMessage='จังหวะยังไม่ตรงหน้าต่างสีเขียว ลองอีกครั้ง';timingStarted=performance.now();render();return;}miniGame=null;timingMessage='';breath=true;score=scoreExposure(technique,verified,positioned,collimated,breath,patientReady,activeCase);xray=makeSyntheticXray(score,profile.missions+1,activeCase.id);profile.missions++;grantXp(profile,Math.max(10,Math.round(score.total/5)));profile.coins+=Math.round(score.total/25);if(!profile.completed.includes(activeCase.id)){profile.completed.push(activeCase.id);grant('anatomy-crystal');}if(profile.questStep===3)profile.questStep=4;if(profile.activeQuests.includes('library-notes')&&!profile.completedQuests.includes('library-notes')){}profile.bestScores[activeCase.id]=Math.max(profile.bestScores[activeCase.id]||0,score.total);step=4;save();gameRef?.events.emit('mission-complete');render();}
function enterDungeon(){if(profile.questStep<5){view='world-map';dialogueName='RESEARCH WING';dialogueText='ปลดล็อก Lost Imaging Lab หลังจบเควสต์วันแรกกับพี่มายา';render();return;}profile.visitedZones=[...new Set([...profile.visitedZones,'noise-lab'])];profile.currentZone='noise-lab';encounter=null;combatFeedback='';view='dungeon';render();}
function onWorldDialogue(kind:string){
  dialogueKind=kind;
  if(kind==='mentor'){dialogueName='MAYA · SENIOR TECHNOLOGIST';dialogueText=profile.questStep===0?'วันนี้มีเคส Chest X-ray เข้ามา ลองไปเตรียมตัวดูนะ รับภารกิจ First Day ไหม?':profile.unlockedSkills.includes('patient-communication')?'ตรวจชื่อ แจ้งขั้นตอน และถามความพร้อมของผู้ป่วยจำลองก่อนเริ่มนะ':'เดินไปคุยกับ Reception เพื่อรับใบส่งตรวจ แล้วค่อยเข้าห้องตรวจ';}
  else if(kind==='reception'){dialogueName='RECEPTION';dialogueText=profile.questStep===1?'นี่คือใบส่งตรวจจำลอง ตรวจชื่อและรายการก่อนเดินไปห้อง X-ray นะ':'สวัสดีค่ะ เคาน์เตอร์ประชาสัมพันธ์แผนกรังสี';}
  else if(kind==='radiologist'){dialogueName='DR. ELIAS · RADIOLOGIST';dialogueText=profile.questStep===4?'มาทบทวนผลการฝึกกัน คะแนนสะท้อนโจทย์เกม ไม่ใช่ความสามารถทางคลินิกนะ':'หลังจบเคส นำผลการฝึกมาคุยกันที่จุดประเมินภาพ';if(profile.questStep===4){profile.questStep=5;profile.chapter=2;profile.relationships.Elias=(profile.relationships.Elias||0)+1;awardQuest('first-exposure',25,80);profile.activeQuests=profile.activeQuests.filter(id=>id!=='first-exposure');grant('student-badge');grant('anatomy-notebook');profile.skillPoints++;save();}}
  else if(kind==='radiology-door'){dialogueName='RADIOLOGY · XR ROOM 01';dialogueText=profile.questStep<2?'ก่อนเข้าเคส ไปพบพี่มายาและรับใบส่งตรวจจำลองให้ครบก่อนนะ':'ประตูห้อง X-ray พร้อมแล้ว เข้าเคส Chest PA เพื่อเริ่มภารกิจ';}
  else if(kind==='engineer'){view='shop';dialogueName='NORA · EQUIPMENT ENGINEER';dialogueText='เครื่องมือฝึกและอุปกรณ์ตกแต่งอยู่ในร้าน ใช้เหรียญในเกมเท่านั้น';}
  else if(kind==='librarian'){view='inventory';inventoryTab='collection';dialogueName='LUNA · LIBRARIAN';dialogueText='เปิดสมุดและแฟ้มภาพที่สะสมได้จากเคสกับการสำรวจ';}
  else if(kind==='student'){dialogueName='KAI · SENIOR STUDENT';dialogueText='ดูภารกิจเสริมที่กระดานได้เลย ถ้าผ่านเคสหนึ่งครั้งก็มีโน้ตกายวิภาคให้เก็บ';}
  else if(kind==='quest-board'){view='library';dialogueName='QUEST BOARD';dialogueText='มีเควสต์หลัก ภารกิจเสริม และงานประจำวันให้เลือก';}
  else if(kind==='hidden-cache'){if(!profile.hiddenFinds.includes('garden-cache')){profile.hiddenFinds.push('garden-cache');grant('image-fragment');grantXp(profile,15);profile.coins+=15;save();dialogueText='พบ Image Fragment ในกล่องสวน! +15 EXP · +15 coins';}else dialogueText='กล่องนี้ถูกค้นพบแล้ว';dialogueName='HIDDEN CACHE';}
  else if(kind==='lab-gate'){dialogueName='LOST IMAGING LAB';if(profile.questStep<5)dialogueText='ต้องจบ First Exposure ก่อนเพื่อเปิดประตูวิจัย';else{dialogueText='ข้อมูลภาพที่หายไปส่งสัญญาณจากห้องแล็บ';enterDungeon();return;}}
  else if(kind==='no-one'){dialogueName='HOSPITAL';dialogueText='เดินเข้าไปใกล้ตัวละครหรือประตู แล้วกด E เพื่อโต้ตอบ';}
  render();
}
function handleCombatResult(result:{correct:boolean;feedback:string;enemy:{id:string;name:string;hp:number;maxHp:number;boss:boolean};question:{question:string;choices:string[];answer:number;feedback:string;topic?:string};skill?:string}){combatCorrect=result.correct;combatFeedback=result.correct?`วิเคราะห์ถูกต้อง${result.skill==='noise-detection'&&result.question.topic==='noise'?' · Noise Detection สร้างผลเพิ่ม':result.skill==='anatomy-scan'&&result.question.topic==='artifact'?' · Anatomy Scan เผย pattern และผลเพิ่ม':''} · ${result.feedback}`:`ลองอีกครั้ง · ${result.feedback}`;if(!result.correct&&!profile.unlockedSkills.includes('critical-thinking')){profile.hp-=8;if(profile.hp<=0){profile.hp=40;combatFeedback='พี่มายาช่วยพากลับมาพัก · ลองวิเคราะห์ใหม่โดยไม่เสียของ';}save();}encounter={...encounter!,enemy:result.enemy};render();}
function handleMonsterDefeated(result:{id:string;boss:boolean;name:string}){if(profile.defeatedMonsters.includes(result.id))return;profile.defeatedMonsters.push(result.id);if(result.name==='Noise Slime')grant('noise-crystal');else if(result.boss){grant('image-fragment',2);grant('noise-crystal',2);}else grant('phantom-dust');grantXp(profile,result.boss?30:12);profile.coins+=result.boss?25:8;save();}
function handleDungeonClear(){if(profile.completedQuests.includes('noise-lab-clear'))return;profile.visitedZones=[...new Set([...profile.visitedZones,'noise-lab'])];awardQuest('noise-lab-clear',60,100,'image-fragment');profile.chapter=Math.max(profile.chapter,3);if(!owns('noise-detector'))grant('noise-detector');save();render();}
function render(){
  if(view==='mission')missionStage();else worldScreen();
  const desired=view==='mission'?'room':profile.currentZone==='noise-lab'?'dungeon':'hospital';
  if(gameRef&&sceneView!==desired){gameRef.scene.start(desired);sceneView=desired;}
  if(gameRef?.canvas){root.querySelector('#game-world')?.appendChild(gameRef.canvas);gameRef.scale.refresh();}
}
export function mountApp(game:Phaser.Game){
  gameRef=game;
  game.events.on('world-dialogue',(kind:string)=>onWorldDialogue(kind));
  game.events.on('request-player-outfit',(reply:(equipped:boolean)=>void)=>reply(profile.equipped.includes('pixel-coat')));
  game.events.on('request-world-position',(reply:(position:{x:number;y:number}|null)=>void)=>reply(profile.worldPositions[profile.currentZone]||null));
  game.events.on('world-position',(position:{zone:string;x:number;y:number})=>{if(position.zone!=='academy'&&position.zone!=='noise-lab')return;profile.currentZone=position.zone;profile.worldPositions[position.zone]={x:position.x,y:position.y};save();});
  game.events.on('quest-world-refresh',()=>render());
  game.events.on('dungeon-encounter',(data:{enemy:NonNullable<typeof encounter>['enemy'];question:NonNullable<typeof encounter>['question']})=>{encounter=data;combatFeedback='';view='dungeon';render();});
  game.events.on('combat-result',handleCombatResult);
  game.events.on('monster-defeated',handleMonsterDefeated);
  game.events.on('dungeon-cleared',handleDungeonClear);
  game.events.on('dungeon-hint',(message:string)=>{dialogueText=message;});
  game.events.on('dungeon-exit',()=>{profile.currentZone='academy';view='hub';encounter=null;combatFeedback='';save();render();});
  game.events.on('dungeon-finish',()=>{if(!profile.completedQuests.includes('noise-lab-clear'))handleDungeonClear();profile.currentZone='academy';dialogueName='MAYA · SENIOR TECHNOLOGIST';dialogueText='Noise Laboratory cleared · Image Fragment และ Noise Detector อยู่ในกระเป๋าแล้ว';view='hub';encounter=null;combatFeedback='';save();render();});
  render();
}
